def somma_cifre(n):
    n = abs(n)
    totale = 0

public class Main {
    static int sommaCifre(int n) {
        n = Math.abs(n);
        int totale = 0;

    while (n > 0) {
        totale += n % 10;
        n /= 10;
    }
    return totale;
}

    public static void main(String[] args) {
        System.out.println(sommaCifre(4721));
        System.out.println(sommaCifre(-305));
        System.out.println(sommaCifre(0));
    }
}

