def secondo_massimo(numeri):
    primo = None
    secondo = None

for x in numeri:
    if primo is None or x > primo:
        secondo = primo
        primo = x

    elif x != primo and (secondo is None or x > secondo):
        secondo = x
return secondo

public class Main {
    static Integer secondoMassimo(int[] numeri) {
        Integer primo = null;
        Integer secondo = null;

for (int x : numeri) {
    if (primo == null || x > primo) {
        secondo = primo;
        primo = x;

        } else if (x != primo && (secondo == null || x > secondo)) {
            secondo = x;
        }
    }
    return secondo;
}

    public static void main(String[] args) {
        System.out.println(secondoMassimo(new int[]{3, 8, 1, 8, 5}));
