def numero_mancante(numeri):
    n = len(numeri)
    atteso = n * (n + 1) // 2

public class Main {
    static int numeroMancante(int[] numeri) {
        int n = numeri.length;
        int atteso = n * (n + 1) / 2;

    int somma = 0;
    for (int x : numeri) {
        somma += x;
    }
    return atteso - somma;
}

    public static void main(String[] args) {
        System.out.println(numeroMancante(new int[]{3, 0, 1}));
        System.out.println(numeroMancante(new int[]{9, 6, 4, 2, 3, 5, 7, 0, 1}));
        System.out.println(numeroMancante(new int[]{1}));
    }
}

def miglior_guadagno(prezzi):
    if not prezzi:
        return 0
    minimo = prezzi[0]
    guadagno = 0

public class Main {
    static int migliorGuadagno(int[] prezzi) {
        if (prezzi.length == 0) return 0;
        int minimo = prezzi[0];
        int guadagno = 0;

    for (int p : prezzi) {
        guadagno = Math.max(guadagno, p - minimo);
        minimo = Math.min(minimo, p);
    }
    return guadagno;
}

    public static void main(String[] args) {
        System.out.println(migliorGuadagno(new int[]{7, 1, 5, 3, 6, 4}));
        System.out.println(migliorGuadagno(new int[]{7, 6, 4, 3, 1}));
        System.out.println(migliorGuadagno(new int[]{}));
    }
}

