def elemento_maggioritario(numeri):
    candidato = None
    voti = 0

for x in numeri:
    if voti == 0:
        candidato = x
    if x == candidato:
        voti += 1
    else:
        voti -= 1

if numeri.count(candidato) > len(numeri) // 2:
    return candidato
return None

public class Main {
    static Integer elementoMaggioritario(int[] numeri) {
        int candidato = 0;
        int voti = 0;

for (int x : numeri) {
    if (voti == 0) candidato = x;
    if (x == candidato) voti++;
    else voti--;
}

    int conteggio = 0;
    for (int x : numeri) {
        if (x == candidato) conteggio++;
    }
    return conteggio > numeri.length / 2 ? candidato : null;
}

    public static void main(String[] args) {
        System.out.println(elementoMaggioritario(new int[]{2, 2, 1, 1, 1, 2, 2}));
        System.out.println(elementoMaggioritario(new int[]{3, 3, 4}));
        System.out.println(elementoMaggioritario(new int[]{1, 2, 3}));
    }
}

