import java.util.Arrays;
public class Main {
    static int[] prodottoTranneSe(int[] numeri) {
        int n = numeri.length;
        int[] risultato = new int[n];

int sinistra = 1;
for (int i = 0; i < n; i++) {
    risultato[i] = sinistra;
    sinistra *= numeri[i];
}

    int destra = 1;
    for (int i = n - 1; i >= 0; i--) {
