def palindromo_valido(frase):
    sx, dx = 0, len(frase) - 1
    while sx < dx:

if not frase[sx].isalnum():
    sx += 1
elif not frase[dx].isalnum():
    dx -= 1

    elif frase[sx].lower() != frase[dx].lower():
        return False
    else:
        sx += 1
        dx -= 1
return True

public class Main {
    static boolean palindromoValido(String frase) {
        int sx = 0, dx = frase.length() - 1;
        while (sx < dx) {
            char a = frase.charAt(sx), b = frase.charAt(dx);

if (!Character.isLetterOrDigit(a)) {
    sx++;
} else if (!Character.isLetterOrDigit(b)) {
    dx--;

        } else if (Character.toLowerCase(a) != Character.toLowerCase(b)) {
            return false;
        } else {
            sx++;
            dx--;
        }
    }
    return true;
}

    public static void main(String[] args) {
        System.out.println(palindromoValido("I topi non avevano nipoti"));
        System.out.println(palindromoValido("Ciao, mondo!"));
        System.out.println(palindromoValido(""));
    }
}

def cifra_cesare(testo, chiave):
    chiave = chiave % 26
    risultato = []

for c in testo:
    if "a" <= c <= "z":
        risultato.append(chr((ord(c) - ord("a") + chiave) % 26 + ord("a")))
    elif "A" <= c <= "Z":
        risultato.append(chr((ord(c) - ord("A") + chiave) % 26 + ord("A")))
    else:
        risultato.append(c)

public class Main {
    static String cifraCesare(String testo, int chiave) {
        chiave = ((chiave % 26) + 26) % 26;
        StringBuilder risultato = new StringBuilder();

for (char c : testo.toCharArray()) {
    if (c >= 'a' && c <= 'z') {
        risultato.append((char) ((c - 'a' + chiave) % 26 + 'a'));
    } else if (c >= 'A' && c <= 'Z') {
        risultato.append((char) ((c - 'A' + chiave) % 26 + 'A'));
    } else {
        risultato.append(c);
    }
}

    public static void main(String[] args) {
        System.out.println(cifraCesare("Ciao Mondo", 3));
        System.out.println(cifraCesare("xyz", 3));
        System.out.println(cifraCesare("Abc", -1));
    }
}

