def romano_a_intero(s):
    valori = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    totale = 0

for i in range(len(s)):
    v = valori[s[i]]
    if i + 1 < len(s) and v < valori[s[i + 1]]:
        totale -= v
    else:
        totale += v
return totale

import java.util.Map;
public class Main {
    static final Map<Character, Integer> VALORI = Map.of(
        'I', 1, 'V', 5, 'X', 10, 'L', 50, 'C', 100, 'D', 500, 'M', 1000);

static int romanoAIntero(String s) {
    int totale = 0;
    for (int i = 0; i < s.length(); i++) {
        int v = VALORI.get(s.charAt(i));
        if (i + 1 < s.length() && v < VALORI.get(s.charAt(i + 1))) {
            totale -= v;
        } else {
            totale += v;
        }
    }
    return totale;
}

    public static void main(String[] args) {
        System.out.println(romanoAIntero("XIV"));
        System.out.println(romanoAIntero("MCMXCIV"));
        System.out.println(romanoAIntero("I"));
    }
}

