def espandi(s, sinistra, destra):
    while sinistra >= 0 and destra < len(s) and s[sinistra] == s[destra]:
        sinistra -= 1
        destra += 1
    return sinistra + 1, destra

def palindroma_piu_lunga(s):
    inizio, fine = 0, 0
    for centro in range(len(s)):
        dispari = espandi(s, centro, centro)
        pari = espandi(s, centro, centro + 1)
        for a, b in (dispari, pari):
            if b - a > fine - inizio:
                inizio, fine = a, b
    return s[inizio:fine]

public class Main {
    static int[] espandi(String s, int sinistra, int destra) {
        while (sinistra >= 0 && destra < s.length() && s.charAt(sinistra) == s.charAt(destra)) {
            sinistra--;
            destra++;
        }
        return new int[]{sinistra + 1, destra};
    }

static String palindromaPiuLunga(String s) {
    int inizio = 0, fine = 0;
    for (int centro = 0; centro < s.length(); centro++) {
        int[] dispari = espandi(s, centro, centro);
        int[] pari = espandi(s, centro, centro + 1);
        for (int[] r : new int[][]{dispari, pari}) {
            if (r[1] - r[0] > fine - inizio) {
                inizio = r[0];
                fine = r[1];
            }
        }
    }
    return s.substring(inizio, fine);
}

    public static void main(String[] args) {
        System.out.println(palindromaPiuLunga("babad"));
        System.out.println(palindromaPiuLunga("cbbd"));
        System.out.println(palindromaPiuLunga("forgeeksskeegfor"));
        System.out.println(palindromaPiuLunga("a"));
    }
}

def conta_palindrome(s):
    totale = 0
    for centro in range(len(s)):
        totale += conta_da_centro(s, centro, centro)
        totale += conta_da_centro(s, centro, centro + 1)
    return totale

public class Main {
    static int contaDaCentro(String s, int sinistra, int destra) {
        int conteggio = 0;
        while (sinistra >= 0 && destra < s.length() && s.charAt(sinistra) == s.charAt(destra)) {
            conteggio++;
            sinistra--;
            destra++;
        }
        return conteggio;
    }

static int contaPalindrome(String s) {
    int totale = 0;
    for (int centro = 0; centro < s.length(); centro++) {
        totale += contaDaCentro(s, centro, centro);
        totale += contaDaCentro(s, centro, centro + 1);
    }
    return totale;
}

    public static void main(String[] args) {
        System.out.println(contaPalindrome("abc"));
        System.out.println(contaPalindrome("aaa"));
        System.out.println(contaPalindrome("abba"));
        System.out.println(contaPalindrome("abcba"));
        System.out.println(contaPalindrome(""));
    }
}

