def sono_anagrammi(a, b):
    if len(a) != len(b):
        return False
    conteggi = {}
    for c in a:
        conteggi[c] = conteggi.get(c, 0) + 1

for c in b:
    conteggi[c] = conteggi.get(c, 0) - 1
    if conteggi[c] < 0:
        return False
return True

import java.util.*;
public class Main {
    static boolean sonoAnagrammi(String a, String b) {
        if (a.length() != b.length()) {
            return false;
        }
        Map<Character, Integer> conteggi = new HashMap<>();
        for (char c : a.toCharArray()) {
            conteggi.put(c, conteggi.getOrDefault(c, 0) + 1);
        }

    for (char c : b.toCharArray()) {
        int resto = conteggi.getOrDefault(c, 0) - 1;
        if (resto < 0) {
            return false;
        }
        conteggi.put(c, resto);
    }
    return true;
}

    public static void main(String[] args) {
        System.out.println(sonoAnagrammi("roma", "amor"));
        System.out.println(sonoAnagrammi("gatto", "gatti"));
        System.out.println(sonoAnagrammi("", ""));
    }
}

def coppia_con_somma(numeri, obiettivo):
    posizioni = {}
    for i, n in enumerate(numeri):
        complemento = obiettivo - n

import java.util.*;
public class Main {
    static int[] coppiaConSomma(int[] numeri, int obiettivo) {
        Map<Integer, Integer> posizioni = new HashMap<>();
        for (int i = 0; i < numeri.length; i++) {
            int complemento = obiettivo - numeri[i];

        if (posizioni.containsKey(complemento)) {
            return new int[]{posizioni.get(complemento), i};
        }
        posizioni.put(numeri[i], i);
    }
    return new int[]{};
}

    public static void main(String[] args) {
        System.out.println(Arrays.toString(coppiaConSomma(new int[]{2, 7, 11, 15}, 9)));
        System.out.println(Arrays.toString(coppiaConSomma(new int[]{3, 2, 4}, 6)));
        System.out.println(Arrays.toString(coppiaConSomma(new int[]{3, 3}, 6)));
        System.out.println(Arrays.toString(coppiaConSomma(new int[]{1, 2}, 7)));
    }
}

def isomorfe(s, t):
    if len(s) != len(t):
        return False
    da_s, da_t = {}, {}

for a, b in zip(s, t):
    if da_s.get(a, b) != b or da_t.get(b, a) != a:
        return False
    da_s[a] = b
    da_t[b] = a
return True

import java.util.*;
public class Main {
    static boolean isomorfe(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }
        Map<Character, Character> daS = new HashMap<>();
        Map<Character, Character> daT = new HashMap<>();

    for (int i = 0; i < s.length(); i++) {
        char a = s.charAt(i);
        char b = t.charAt(i);
        if (daS.getOrDefault(a, b) != b || daT.getOrDefault(b, a) != a) {
            return false;
        }
        daS.put(a, b);
        daT.put(b, a);
    }
    return true;
}

    public static void main(String[] args) {
        System.out.println(isomorfe("egg", "add"));
        System.out.println(isomorfe("foo", "bar"));
        System.out.println(isomorfe("badc", "baba"));
        System.out.println(isomorfe("", ""));
    }
}

def segue_schema(schema, frase):
    parole = frase.split(" ")
    if len(schema) != len(parole):
        return False
    lettera_parola, parola_lettera = {}, {}

for c, p in zip(schema, parole):
    if lettera_parola.get(c, p) != p or parola_lettera.get(p, c) != c:
        return False
    lettera_parola[c] = p
    parola_lettera[p] = c
return True

import java.util.*;
public class Main {
    static boolean segueSchema(String schema, String frase) {
        String[] parole = frase.split(" ");
        if (schema.length() != parole.length) {
            return false;
        }
        Map<Character, String> letteraParola = new HashMap<>();
        Map<String, Character> parolaLettera = new HashMap<>();

    for (int i = 0; i < parole.length; i++) {
        char c = schema.charAt(i);
        String p = parole[i];
        if (!letteraParola.getOrDefault(c, p).equals(p) || parolaLettera.getOrDefault(p, c) != c) {
            return false;
        }
        letteraParola.put(c, p);
        parolaLettera.put(p, c);
    }
    return true;
}

    public static void main(String[] args) {
        System.out.println(segueSchema("abba", "cane gatto gatto cane"));
        System.out.println(segueSchema("abba", "cane gatto gatto pesce"));
        System.out.println(segueSchema("abba", "cane cane cane cane"));
        System.out.println(segueSchema("ab", "cane"));
    }
}

def raggruppa_anagrammi(parole):
    gruppi = {}
    for parola in parole:
        gruppi.setdefault(chiave_ordinata(parola), []).append(parola)

import java.util.*;
public class Main {
    static String chiaveOrdinata(String parola) {
        char[] lettere = parola.toCharArray();
        Arrays.sort(lettere);
        return new String(lettere);
    }

static List<List<String>> raggruppaAnagrammi(String[] parole) {
    Map<String, List<String>> gruppi = new TreeMap<>();
    for (String parola : parole) {
        gruppi.computeIfAbsent(chiaveOrdinata(parola), k -> new ArrayList<>()).add(parola);
    }

    List<List<String>> risultato = new ArrayList<>();
    for (List<String> gruppo : gruppi.values()) {
        Collections.sort(gruppo);
        risultato.add(gruppo);
    }
    return risultato;
}

    public static void main(String[] args) {
        System.out.println(raggruppaAnagrammi(new String[]{"eat", "tea", "tan", "ate", "nat", "bat"}));
        System.out.println(raggruppaAnagrammi(new String[]{"roma", "amor", "ramo", "mora"}));
        System.out.println(raggruppaAnagrammi(new String[]{"sole"}));
        System.out.println(raggruppaAnagrammi(new String[]{}));
    }
}

def k_frequenti(numeri, k):
    conteggi = {}
    for n in numeri:
        conteggi[n] = conteggi.get(n, 0) + 1

secchi = [[] for _ in range(len(numeri) + 1)]
for n, volte in conteggi.items():
    secchi[volte].append(n)

risultato = []
for volte in range(len(numeri), 0, -1):
    for n in sorted(secchi[volte]):
        risultato.append(n)
        if len(risultato) == k:
            return risultato
return risultato

import java.util.*;
public class Main {
    static List<Integer> kFrequenti(int[] numeri, int k) {
        Map<Integer, Integer> conteggi = new HashMap<>();
        for (int n : numeri) {
            conteggi.put(n, conteggi.getOrDefault(n, 0) + 1);
        }

