def sequenza_piu_lunga(numeri):
    insieme = set(numeri)
    migliore = 0

for n in insieme:
    if n - 1 not in insieme:
        fine = n
        while fine + 1 in insieme:
            fine += 1
        migliore = max(migliore, fine - n + 1)
return migliore

import java.util.*;
public class Main {
    static int sequenzaPiuLunga(int[] numeri) {
        Set<Integer> insieme = new HashSet<>();
        for (int n : numeri) {
            insieme.add(n);
        }
        int migliore = 0;

    for (int n : insieme) {
        if (!insieme.contains(n - 1)) {
            int fine = n;
            while (insieme.contains(fine + 1)) {
                fine++;
            }
            migliore = Math.max(migliore, fine - n + 1);
        }
    }
    return migliore;
}

    public static void main(String[] args) {
        System.out.println(sequenzaPiuLunga(new int[]{100, 4, 200, 1, 3, 2}));
        System.out.println(sequenzaPiuLunga(new int[]{0, 3, 7, 2, 5, 8, 4, 6, 0, 1}));
        System.out.println(sequenzaPiuLunga(new int[]{-2, -1, 5}));
        System.out.println(sequenzaPiuLunga(new int[]{}));
    }
}

def sudoku_valido(griglia):
    visti = set()
    for r in range(9):
        for c in range(9):
            cifra = griglia[r][c]
            if cifra == ".":
                continue

        chiavi = (f"r{r}{cifra}", f"c{c}{cifra}", f"q{r // 3}{c // 3}{cifra}")
        for chiave in chiavi:
            if chiave in visti:
                return False
            visti.add(chiave)
return True

