    static boolean sudokuValido(String[] griglia) {
        Set<String> visti = new HashSet<>();
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                char cifra = griglia[r].charAt(c);
                if (cifra == '.') {
                    continue;
                }

            String[] chiavi = {"r" + r + cifra, "c" + c + cifra, "q" + (r / 3) + (c / 3) + cifra};
            for (String chiave : chiavi) {
                if (!visti.add(chiave)) {
                    return false;
                }
            }
        }
    }
