def media_massima(numeri, k):
    somma = sum(numeri[:k])
    migliore = somma

public class Main {
    static double mediaMassima(int[] numeri, int k) {
        int somma = 0;
        for (int i = 0; i < k; i++) {
            somma += numeri[i];
        }
        int migliore = somma;

    for (int i = k; i < numeri.length; i++) {
        somma += numeri[i] - numeri[i - k];
        migliore = Math.max(migliore, somma);
    }
    return (double) migliore / k;
}

    public static void main(String[] args) {
        System.out.println(mediaMassima(new int[]{1, 12, -5, -6, 50, 3}, 4));
