def contiene_permutazione(s1, s2):
    if len(s1) > len(s2):
        return False
    conta1 = [0] * 26
    finestra = [0] * 26

for i in range(len(s1)):
    conta1[ord(s1[i]) - ord("a")] += 1
    finestra[ord(s2[i]) - ord("a")] += 1
if conta1 == finestra:
    return True

for i in range(len(s1), len(s2)):
    finestra[ord(s2[i]) - ord("a")] += 1
    finestra[ord(s2[i - len(s1)]) - ord("a")] -= 1
    if conta1 == finestra:
        return True
return False

