def conta_forza_bruta(numeri, k):
    totale = 0
    for i in range(len(numeri)):
        somma = 0
        for j in range(i, len(numeri)):
            somma += numeri[j]
            if somma % k == 0:
                totale += 1
    return totale

public class Main {
    static int contaDivisibili(int[] numeri, int k) {
        int[] conteggi = new int[k];
        conteggi[0] = 1;
        int somma = 0;
        int risultato = 0;

    for (int x : numeri) {
        somma += x;
        int resto = ((somma % k) + k) % k;
        risultato += conteggi[resto];
        conteggi[resto]++;
    }
    return risultato;
}

static int contaForzaBruta(int[] numeri, int k) {
    int totale = 0;
    for (int i = 0; i < numeri.length; i++) {
        int somma = 0;
        for (int j = i; j < numeri.length; j++) {
            somma += numeri[j];
            if (somma % k == 0) {
                totale++;
            }
        }
    }
    return totale;
}

    public static void main(String[] args) {
        int[] esempio = {4, 5, 0, -2, -3, 1};
        System.out.println(contaDivisibili(esempio, 5));
        System.out.println(contaDivisibili(new int[]{0, 0}, 3));
        System.out.println(contaDivisibili(new int[]{5}, 9));
        System.out.println(contaDivisibili(esempio, 5) == contaForzaBruta(esempio, 5));
    }
}

def costruisci_prefissi(matrice):
    righe, colonne = len(matrice), len(matrice[0])
    p = [[0] * (colonne + 1) for _ in range(righe + 1)]

for i in range(righe):
    for j in range(colonne):
        p[i + 1][j + 1] = matrice[i][j] + p[i][j + 1] + p[i + 1][j] - p[i][j]
return p

public class Main {
    static int[][] costruisciPrefissi(int[][] matrice) {
        int righe = matrice.length;
        int colonne = matrice[0].length;
        int[][] p = new int[righe + 1][colonne + 1];

    for (int i = 0; i < righe; i++) {
        for (int j = 0; j < colonne; j++) {
            p[i + 1][j + 1] = matrice[i][j] + p[i][j + 1] + p[i + 1][j] - p[i][j];
        }
    }
    return p;
}

static int sommaRettangolo(int[][] p, int r1, int c1, int r2, int c2) {
    return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1];
}

    public static void main(String[] args) {
        int[][] matrice = {{3, 0, 1, 4}, {5, 6, 3, 2}, {1, 2, 0, 1}};
        int[][] p = costruisciPrefissi(matrice);
        System.out.println(sommaRettangolo(p, 1, 1, 2, 2));
        System.out.println(sommaRettangolo(p, 0, 0, 2, 3));
        System.out.println(sommaRettangolo(p, 2, 3, 2, 3));
    }
}

