def trova_bordo(numeri, x, cerca_prima):
    sinistra, destra = 0, len(numeri) - 1
    risultato = -1

while sinistra <= destra:
    medio = (sinistra + destra) // 2
    if numeri[medio] == x:
        risultato = medio
        if cerca_prima:
            destra = medio - 1
        else:
            sinistra = medio + 1

    elif numeri[medio] < x:
        sinistra = medio + 1
    else:
        destra = medio - 1
return risultato

