while (sinistra <= destra) {
    int medio = (sinistra + destra) / 2;
    if (numeri[medio] == x) {
        risultato = medio;
        if (cercaPrima) {
            destra = medio - 1;
        } else {
            sinistra = medio + 1;
        }

        } else if (numeri[medio] < x) {
            sinistra = medio + 1;
