public class Main {
    static long fibonacciMemo(int n, Map<Integer, Long> memo) {
        if (n <= 1) {
            return n;
        }
        if (memo.containsKey(n)) {
            return memo.get(n);
        }

    long valore = fibonacciMemo(n - 1, memo) + fibonacciMemo(n - 2, memo);
    memo.put(n, valore);
    return valore;
}

static long fibonacci(int n) {
    return fibonacciMemo(n, new HashMap<>());
