def bubble_sort(numeri):
    n = len(numeri)
    for giro in range(n - 1):
        scambiato = False

for i in range(n - 1 - giro):
    if numeri[i] > numeri[i + 1]:
        numeri[i], numeri[i + 1] = numeri[i + 1], numeri[i]
        scambiato = True

    if not scambiato:
        break
return numeri

import java.util.Arrays;
public class Main {
    static int[] bubbleSort(int[] numeri) {
        int n = numeri.length;
        for (int giro = 0; giro < n - 1; giro++) {
            boolean scambiato = false;

for (int i = 0; i < n - 1 - giro; i++) {
    if (numeri[i] > numeri[i + 1]) {
        int temp = numeri[i];
        numeri[i] = numeri[i + 1];
        numeri[i + 1] = temp;
        scambiato = true;
    }
}

        if (!scambiato) {
            break;
        }
    }
    return numeri;
}

    public static void main(String[] args) {
        System.out.println(Arrays.toString(bubbleSort(new int[]{5, 1, 4, 2, 8})));
        System.out.println(Arrays.toString(bubbleSort(new int[]{1, 2, 3})));
