def ordina_per_fusione(lista):
    if len(lista) <= 1:
        return lista
    meta = len(lista) // 2
    sinistra = ordina_per_fusione(lista[:meta])
    destra = ordina_per_fusione(lista[meta:])
    return fondi(sinistra, destra)

import java.util.*;
