    static int[] fondi(int[] a, int[] b) {
        int[] risultato = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;
        while (i < a.length && j < b.length) {
            if (a[i] <= b[j]) {
                risultato[k++] = a[i++];
            } else {
                risultato[k++] = b[j++];
            }
        }

    while (i < a.length) risultato[k++] = a[i++];
    while (j < b.length) risultato[k++] = b[j++];
    return risultato;
}

