def k_grandi(numeri, k):
    if k <= 0:
        return []
    heap = []
    for x in numeri:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)
    return sorted(heap, reverse=True)

