static int[][] puntiVicini(int[][] punti, int k) {
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> distanza(b) - distanza(a));
    for (int[] p : punti) {
        heap.offer(p);
        if (heap.size() > k) heap.poll();
    }
    int[][] risultato = new int[heap.size()][];
    for (int i = risultato.length - 1; i >= 0; i--) risultato[i] = heap.poll();
    return risultato;
}

