import heapq
class MedianaFlusso:
    def __init__(self):
        self.basso = []
        self.alto = []

def aggiungi(self, x):
    heapq.heappush(self.basso, -x)
    heapq.heappush(self.alto, -heapq.heappop(self.basso))
    if len(self.alto) > len(self.basso):
        heapq.heappush(self.basso, -heapq.heappop(self.alto))

def mediana(self):
    if len(self.basso) > len(self.alto):
        return float(-self.basso[0])
    return (-self.basso[0] + self.alto[0]) / 2

import java.util.*;
public class Main {
    static class MedianaFlusso {
        PriorityQueue<Integer> basso = new PriorityQueue<>(Collections.reverseOrder());
        PriorityQueue<Integer> alto = new PriorityQueue<>();

void aggiungi(int x) {
    basso.offer(x);
    alto.offer(basso.poll());
    if (alto.size() > basso.size()) basso.offer(alto.poll());
}

    double mediana() {
        if (basso.size() > alto.size()) return basso.peek();
        return (basso.peek() + alto.peek()) / 2.0;
    }
}

