public class Main {
    static boolean eBipartito(int[][] grafo) {
        int[] colore = new int[grafo.length];
        Arrays.fill(colore, -1);
        for (int partenza = 0; partenza < grafo.length; partenza++) {
            if (colore[partenza] != -1) {
                continue;
