        self.valore = valore
        self.vicini = []

def clona(nodo, copie):
    if nodo is None:
        return None
    if nodo in copie:
        return copie[nodo]
    copia = Nodo(nodo.valore)
    copie[nodo] = copia
    for vicino in nodo.vicini:
        copia.vicini.append(clona(vicino, copie))
    return copia

