import java.util.*;
public class Main {
    static int[] dijkstra(int n, int[][] archi, int sorgente) {
        List<List<int[]>> grafo = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            grafo.add(new ArrayList<>());
        }
        for (int[] a : archi) {
            grafo.get(a[0]).add(new int[]{a[1], a[2]});
        }
        int[] distanza = new int[n];
        Arrays.fill(distanza, Integer.MAX_VALUE);
        distanza[sorgente] = 0;

PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
heap.add(new int[]{0, sorgente});
while (!heap.isEmpty()) {
    int[] cima = heap.poll();
    int d = cima[0], nodo = cima[1];
    if (d > distanza[nodo]) {
        continue;
    }
    for (int[] arco : grafo.get(nodo)) {
        int nuova = d + arco[1];
        if (nuova < distanza[arco[0]]) {
            distanza[arco[0]] = nuova;
            heap.add(new int[]{nuova, arco[0]});
        }
    }

    }
    for (int i = 0; i < n; i++) {
        if (distanza[i] == Integer.MAX_VALUE) {
            distanza[i] = -1;
        }
    }
    return distanza;
}

