def lunghezza_scala(inizio, fine, parole):
    dizionario = set(parole)
    if fine not in dizionario:
        return 0
    coda = deque([inizio])
    visitate = {inizio}
    passi = 1

while coda:
    for _ in range(len(coda)):
        parola = coda.popleft()
        if parola == fine:
            return passi
        for i in range(len(parola)):
            for lettera in "abcdefghijklmnopqrstuvwxyz":
                nuova = parola[:i] + lettera + parola[i + 1:]
                if nuova in dizionario and nuova not in visitate:
                    visitate.add(nuova)
                    coda.append(nuova)
    passi += 1
return 0

import java.util.*;
public class Main {
    static int lunghezzaScala(String inizio, String fine, List<String> parole) {
        Set<String> dizionario = new HashSet<>(parole);
        if (!dizionario.contains(fine)) {
            return 0;
        }
        ArrayDeque<String> coda = new ArrayDeque<>();
        coda.add(inizio);
        Set<String> visitate = new HashSet<>();
        visitate.add(inizio);
        int passi = 1;

while (!coda.isEmpty()) {
    for (int k = coda.size(); k > 0; k--) {
        String parola = coda.poll();
