public class Main {
    static int trova(int[] padre, int x) {
        while (padre[x] != x) {
            padre[x] = padre[padre[x]];
            x = padre[x];
        }
        return x;
    }

static int numeroProvince(int[][] collegato) {
    int n = collegato.length;
    int[] padre = new int[n];
    for (int i = 0; i < n; i++) {
        padre[i] = i;
    }
    int province = n;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (collegato[i][j] == 1) {
                int ri = trova(padre, i), rj = trova(padre, j);
                if (ri != rj) {
                    padre[ri] = rj;
                    province--;
                }
            }
        }
    }
    return province;
}

