class InsiemiDisgiunti:
    def __init__(self, n):
        self.padre = list(range(n))
        self.rango = [0] * n

def trova(self, x):
    if self.padre[x] != x:
        self.padre[x] = self.trova(self.padre[x])
    return self.padre[x]

def unisci(self, a, b):
    ra, rb = self.trova(a), self.trova(b)
    if ra == rb:
        return False
    if self.rango[ra] < self.rango[rb]:
        ra, rb = rb, ra
    self.padre[rb] = ra
    if self.rango[ra] == self.rango[rb]:
        self.rango[ra] += 1
    return True

