    dp = [0] * (n + 1)

public class Main {
    static int costoMinimo(int[] costo) {
        int n = costo.length;
        int[] dp = new int[n + 1];

    for (int i = 2; i <= n; i++) {
        int daUno = dp[i - 1] + costo[i - 1];
        int daDue = dp[i - 2] + costo[i - 2];
        dp[i] = Math.min(daUno, daDue);
    }
    return dp[n];
}

