def percorsi(righe, colonne):
    if righe == 0 or colonne == 0:
        return 0
    dp = [[0] * colonne for _ in range(righe)]

for i in range(righe):
    dp[i][0] = 1
for j in range(colonne):
    dp[0][j] = 1

for i in range(1, righe):
    for j in range(1, colonne):
        dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
return dp[righe - 1][colonne - 1]

public class Main {
    static int percorsi(int righe, int colonne) {
        if (righe == 0 || colonne == 0) {
            return 0;
        }
        int[][] dp = new int[righe][colonne];

for (int i = 0; i < righe; i++) {
    dp[i][0] = 1;
}
for (int j = 0; j < colonne; j++) {
    dp[0][j] = 1;
}

    for (int i = 1; i < righe; i++) {
        for (int j = 1; j < colonne; j++) {
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
        }
    }
    return dp[righe - 1][colonne - 1];
}

    public static void main(String[] args) {
        System.out.println(percorsi(3, 7));
        System.out.println(percorsi(3, 2));
