}

def ladro_circolare(soldi):
    if not soldi:
        return 0
    if len(soldi) == 1:
        return soldi[0]

senza_ultima = ladro_lineare(soldi[:-1])
senza_prima = ladro_lineare(soldi[1:])
return max(senza_ultima, senza_prima)

public class Main {
    static int ladroLineare(int[] soldi, int inizio, int fine) {
        int dueFa = 0;
        int unoFa = 0;
        for (int i = inizio; i <= fine; i++) {
            int nuovo = Math.max(unoFa, dueFa + soldi[i]);
            dueFa = unoFa;
            unoFa = nuovo;
        }
        return unoFa;
    }

static int ladroCircolare(int[] soldi) {
    int n = soldi.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return soldi[0];
    }

    int senzaUltima = ladroLineare(soldi, 0, n - 2);
    int senzaPrima = ladroLineare(soldi, 1, n - 1);
    return Math.max(senzaUltima, senzaPrima);
}

    public static void main(String[] args) {
        System.out.println(ladroCircolare(new int[]{2, 3, 2}));
        System.out.println(ladroCircolare(new int[]{1, 2, 3, 1}));
        System.out.println(ladroCircolare(new int[]{5}));
    }
}

