def prima_posizione(finali, x):
    sinistra, destra = 0, len(finali)
    while sinistra < destra:
        mezzo = (sinistra + destra) // 2
        if finali[mezzo] < x:
            sinistra = mezzo + 1
        else:
            destra = mezzo
    return sinistra

def crescente_piu_lunga(numeri):
    finali = []
    for x in numeri:
        pos = prima_posizione(finali, x)
        if pos == len(finali):
            finali.append(x)
        else:
            finali[pos] = x
    return len(finali)

public class Main {
    static int primaPosizione(int[] finali, int lunghezza, int x) {
        int sinistra = 0;
        int destra = lunghezza;
        while (sinistra < destra) {
            int mezzo = (sinistra + destra) / 2;
            if (finali[mezzo] < x) {
                sinistra = mezzo + 1;
            } else {
                destra = mezzo;
            }
        }
        return sinistra;
    }

static int crescentePiuLunga(int[] numeri) {
    int[] finali = new int[numeri.length];
    int lunghezza = 0;
    for (int x : numeri) {
        int pos = primaPosizione(finali, lunghezza, x);
        finali[pos] = x;
        if (pos == lunghezza) {
            lunghezza++;
        }
    }
    return lunghezza;
}

    public static void main(String[] args) {
        System.out.println(crescentePiuLunga(new int[]{10, 9, 2, 5, 3, 7, 101, 18}));
        System.out.println(crescentePiuLunga(new int[]{0, 1, 0, 3, 2, 3}));
