    }
}

def modi_decodifica(cifre):
    n = len(cifre)
    if n == 0:
        return 0
    dp = [0] * (n + 1)
    dp[0] = 1

for i in range(1, n + 1):
    if cifre[i - 1] != "0":
        dp[i] += dp[i - 1]

    if i >= 2:
        coppia = int(cifre[i - 2:i])
        if 10 <= coppia <= 26:
            dp[i] += dp[i - 2]
return dp[n]

public class Main {
    static int modiDecodifica(String cifre) {
        int n = cifre.length();
        if (n == 0) {
            return 0;
        }
        int[] dp = new int[n + 1];
        dp[0] = 1;

for (int i = 1; i <= n; i++) {
    if (cifre.charAt(i - 1) != '0') {
        dp[i] += dp[i - 1];
    }

        if (i >= 2) {
            int coppia = Integer.parseInt(cifre.substring(i - 2, i));
            if (coppia >= 10 && coppia <= 26) {
                dp[i] += dp[i - 2];
            }
        }
    }
    return dp[n];
}

    public static void main(String[] args) {
        System.out.println(modiDecodifica("226"));
        System.out.println(modiDecodifica("11106"));
        System.out.println(modiDecodifica("06"));
    }
}

