def prodotto_lento(numeri):
    migliore = numeri[0]
    for i in range(len(numeri)):
        prodotto = 1
        for j in range(i, len(numeri)):
            prodotto *= numeri[j]
            migliore = max(migliore, prodotto)
    return migliore

public class Main {
    static int prodottoMassimo(int[] numeri) {
        int massimo = numeri[0];
        int minimo = numeri[0];
        int migliore = numeri[0];

    for (int i = 1; i < numeri.length; i++) {
        int x = numeri[i];
        if (x < 0) {
            int temp = massimo;
            massimo = minimo;
            minimo = temp;
        }
        massimo = Math.max(x, massimo * x);
        minimo = Math.min(x, minimo * x);
        migliore = Math.max(migliore, massimo);
    }
    return migliore;
}

static int prodottoLento(int[] numeri) {
    int migliore = numeri[0];
    for (int i = 0; i < numeri.length; i++) {
        int prodotto = 1;
        for (int j = i; j < numeri.length; j++) {
            prodotto *= numeri[j];
            migliore = Math.max(migliore, prodotto);
        }
    }
    return migliore;
}

