def tabella_lcs(a, b):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp

def ricostruisci(a, b, dp):
    i, j = len(a), len(b)
    lettere = []
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            lettere.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return "".join(reversed(lettere))

public class Main {
    static int[][] tabellaLcs(String a, String b) {
        int n = a.length();
        int m = b.length();
        int[][] dp = new int[n + 1][m + 1];

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a.charAt(i - 1) == b.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp;
}

static String ricostruisci(String a, String b, int[][] dp) {
    int i = a.length();
    int j = b.length();
    StringBuilder lettere = new StringBuilder();

    while (i > 0 && j > 0) {
        if (a.charAt(i - 1) == b.charAt(j - 1)) {
            lettere.append(a.charAt(i - 1));
            i--;
            j--;
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            i--;
        } else {
            j--;
        }
    }
    return lettere.reverse().toString();
}

static void mostra(String a, String b) {
    int[][] dp = tabellaLcs(a, b);
    String comune = ricostruisci(a, b, dp);
    System.out.println(dp[a.length()][b.length()] + " '" + comune + "'");
}

    public static void main(String[] args) {
        mostra("abcde", "ace");
        mostra("programma", "grammatica");
        mostra("abc", "xyz");
    }
}

