for i in range(1, n + 1):
    for j in range(1, m + 1):
        if a[i - 1] == b[j - 1]:
            dp[i][j] = dp[i - 1][j - 1]

public class Main {
    static int distanza(String a, String b) {
        int n = a.length();
        int m = b.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            dp[i][0] = i;
        }
        for (int j = 0; j <= m; j++) {
            dp[0][j] = j;
        }

for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
        if (a.charAt(i - 1) == b.charAt(j - 1)) {
            dp[i][j] = dp[i - 1][j - 1];

            } else {
                int cancella = dp[i - 1][j];
                int inserisci = dp[i][j - 1];
                int sostituisci = dp[i - 1][j - 1];
                dp[i][j] = 1 + Math.min(cancella, Math.min(inserisci, sostituisci));
            }
        }
    }
    return dp[n][m];
}

    static void mostra(String a, String b) {
        System.out.println("'" + a + "' -> '" + b + "': " + distanza(a, b));
    }
    public static void main(String[] args) {
        mostra("gatto", "gatti");
        mostra("kitten", "sitting");
        mostra("", "ciao");
    }
}

def zaino(pesi, valori, capacita):
    n = len(pesi)
    dp = [[0] * (capacita + 1) for _ in range(n + 1)]

for i in range(1, n + 1):
    peso, valore = pesi[i - 1], valori[i - 1]
    for c in range(capacita + 1):
        dp[i][c] = dp[i - 1][c]
        if peso <= c:
            dp[i][c] = max(dp[i][c], dp[i - 1][c - peso] + valore)

import java.util.*;
public class Main {
    static int zaino(int[] pesi, int[] valori, int capacita, List<Integer> scelti) {
        int n = pesi.length;
        int[][] dp = new int[n + 1][capacita + 1];

for (int i = 1; i <= n; i++) {
    int peso = pesi[i - 1];
    int valore = valori[i - 1];
    for (int c = 0; c <= capacita; c++) {
        dp[i][c] = dp[i - 1][c];
        if (peso <= c) {
            dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - peso] + valore);
        }
    }
}

    int c = capacita;
    for (int i = n; i > 0; i--) {
        if (dp[i][c] != dp[i - 1][c]) {
            scelti.add(i - 1);
            c -= pesi[i - 1];
        }
    }
    Collections.reverse(scelti);
    return dp[n][capacita];
}

    static void mostra(int[] pesi, int[] valori, int capacita) {
        List<Integer> scelti = new ArrayList<>();
        int totale = zaino(pesi, valori, capacita, scelti);
        System.out.println(totale + " " + scelti);
    }
    public static void main(String[] args) {
        mostra(new int[]{1, 3, 4, 5}, new int[]{1, 4, 5, 7}, 7);
        mostra(new int[]{2, 3, 4}, new int[]{3, 4, 5}, 5);
        mostra(new int[]{5}, new int[]{10}, 4);
    }
}

