def puo_arrivare(salti):
    massimo = 0
    for i, salto in enumerate(salti):
        if i > massimo:
            return False
        massimo = max(massimo, i + salto)
    return True

def salti_minimi(salti):
    if not puo_arrivare(salti):
        return -1
    passi = 0
    fine_livello = 0
    piu_lontano = 0

for i in range(len(salti) - 1):
    piu_lontano = max(piu_lontano, i + salti[i])
    if i == fine_livello:
        passi += 1
        fine_livello = piu_lontano
return passi

public class Main {
    static boolean puoArrivare(int[] salti) {
        int massimo = 0;
        for (int i = 0; i < salti.length; i++) {
            if (i > massimo) {
                return false;
            }
            massimo = Math.max(massimo, i + salti[i]);
        }
        return true;
    }

static int saltiMinimi(int[] salti) {
    if (!puoArrivare(salti)) {
        return -1;
    }
    int passi = 0;
    int fineLivello = 0;
    int piuLontano = 0;

    for (int i = 0; i < salti.length - 1; i++) {
        piuLontano = Math.max(piuLontano, i + salti[i]);
        if (i == fineLivello) {
            passi++;
            fineLivello = piuLontano;
        }
    }
    return passi;
}

    public static void main(String[] args) {
        int[][] casi = {{2, 3, 1, 1, 4}, {3, 2, 1, 0, 4}, {0}};
        for (int[] salti : casi) {
            System.out.println(puoArrivare(salti) + " " + saltiMinimi(salti));
        }
    }
}

def stazione_partenza(benzina, costo):
