        serbatoio = 0
return partenza

def giro_riuscito(benzina, costo, partenza):
    n = len(benzina)
    serbatoio = 0
    for passo in range(n):
        i = (partenza + passo) % n
        serbatoio += benzina[i] - costo[i]
        if serbatoio < 0:
            return False
    return True

public class Main {
    static int stazionePartenza(int[] benzina, int[] costo) {
        int totale = 0;
        for (int i = 0; i < benzina.length; i++) {
            totale += benzina[i] - costo[i];
        }
        if (totale < 0) {
            return -1;
        }

    int partenza = 0;
    int serbatoio = 0;
    for (int i = 0; i < benzina.length; i++) {
        serbatoio += benzina[i] - costo[i];
        if (serbatoio < 0) {
            partenza = i + 1;
            serbatoio = 0;
        }
    }
    return partenza;
}

static boolean giroRiuscito(int[] benzina, int[] costo, int partenza) {
    int n = benzina.length;
    int serbatoio = 0;
    for (int passo = 0; passo < n; passo++) {
        int i = (partenza + passo) % n;
        serbatoio += benzina[i] - costo[i];
        if (serbatoio < 0) {
            return false;
        }
    }
    return true;
}

    public static void main(String[] args) {
