def esiste_parola(griglia, parola):
    righe, colonne = len(griglia), len(griglia[0])
    def cerca(r, c, k):
        if k == len(parola):
            return True
        if r < 0 or r >= righe or c < 0 or c >= colonne:
            return False
        if griglia[r][c] != parola[k]:
            return False

for r in range(righe):
    for c in range(colonne):
        if cerca(r, c, 0):
            return True
return False

public class Main {
    static boolean cerca(char[][] griglia, String parola, int r, int c, int k) {
        if (k == parola.length()) {
            return true;
        }
        if (r < 0 || r >= griglia.length || c < 0 || c >= griglia[0].length) {
            return false;
        }
        if (griglia[r][c] != parola.charAt(k)) {
            return false;
        }

    char lettera = griglia[r][c];
    griglia[r][c] = '#';
    boolean trovato = cerca(griglia, parola, r + 1, c, k + 1)
            || cerca(griglia, parola, r - 1, c, k + 1)
            || cerca(griglia, parola, r, c + 1, k + 1)
            || cerca(griglia, parola, r, c - 1, k + 1);
    griglia[r][c] = lettera;
    return trovato;
}

static boolean esisteParola(char[][] griglia, String parola) {
    for (int r = 0; r < griglia.length; r++) {
        for (int c = 0; c < griglia[0].length; c++) {
            if (cerca(griglia, parola, r, c, 0)) {
                return true;
            }
        }
    }
    return false;
}

    public static void main(String[] args) {
        char[][] griglia = {"ABCE".toCharArray(), "SFCS".toCharArray(), "ADEE".toCharArray()};
        System.out.println(esisteParola(griglia, "ABCCED"));
        System.out.println(esisteParola(griglia, "SEE"));
        System.out.println(esisteParola(griglia, "ABCB"));
    }
}

