def piazza(riga):
    if riga == n:
        return 1
    totale = 0
    for c in range(n):
        if c in colonne or riga - c in diagonali or riga + c in antidiagonali:
            continue

for n in (1, 4, 6, 8):
    print(n, conta_regine(n))
print(conta_regine(3))

public class Main {
    static int contaRegine(int n) {
        boolean[] colonne = new boolean[n];
        boolean[] diagonali = new boolean[2 * n];
        boolean[] antidiagonali = new boolean[2 * n];
        return piazza(0, n, colonne, diagonali, antidiagonali);
    }

static int piazza(int riga, int n, boolean[] colonne, boolean[] diagonali, boolean[] antidiagonali) {
    if (riga == n) {
        return 1;
    }
    int totale = 0;
    for (int c = 0; c < n; c++) {
        int d = riga - c + n - 1;
        int a = riga + c;
        if (colonne[c] || diagonali[d] || antidiagonali[a]) {
            continue;
        }

        colonne[c] = true;
        diagonali[d] = true;
        antidiagonali[a] = true;
        totale += piazza(riga + 1, n, colonne, diagonali, antidiagonali);
        colonne[c] = false;
        diagonali[d] = false;
        antidiagonali[a] = false;
    }
    return totale;
}

    public static void main(String[] args) {
        for (int n : new int[]{1, 4, 6, 8}) {
            System.out.println(n + " " + contaRegine(n));
        }
        System.out.println(contaRegine(3));
    }
}

