        self.dimensione = 0
    def indice(self, chiave):
        h = 0
        for carattere in chiave:
            h = (h * 31 + ord(carattere)) % len(self.secchi)
        return h

def metti(self, chiave, valore):
    secchio = self.secchi[self.indice(chiave)]
    for coppia in secchio:
        if coppia[0] == chiave:
            coppia[1] = valore
            return
    secchio.append([chiave, valore])
    self.dimensione += 1

def prendi(self, chiave):
    for k, v in self.secchi[self.indice(chiave)]:
        if k == chiave:
            return v
    return None

def rimuovi(self, chiave):
    secchio = self.secchi[self.indice(chiave)]
    for i in range(len(secchio)):
        if secchio[i][0] == chiave:
            secchio.pop(i)
            self.dimensione -= 1
            return True
    return False

