class CacheLRU:
    def __init__(self, capacita):
        self.capacita = capacita
        self.mappa = {}
        self.testa = Nodo()
        self.coda = Nodo()
        self.testa.succ = self.coda
        self.coda.prec = self.testa

def metti(self, chiave, valore):
    if chiave in self.mappa:
        self.stacca(self.mappa[chiave])
    elif len(self.mappa) == self.capacita:
        vecchio = self.coda.prec
        self.stacca(vecchio)
        del self.mappa[vecchio.chiave]
    nodo = Nodo(chiave, valore)
    self.mappa[chiave] = nodo
    self.in_testa(nodo)

import java.util.*;
public class Main {
    static class Nodo {
        int chiave;
        int valore;
        Nodo prec;
        Nodo succ;
        Nodo(int chiave, int valore) {
            this.chiave = chiave;
            this.valore = valore;
        }
    }

static class CacheLRU {
    private final int capacita;
    private final Map<Integer, Nodo> mappa = new HashMap<>();
    private final Nodo testa = new Nodo(0, 0);
    private final Nodo coda = new Nodo(0, 0);
    CacheLRU(int capacita) {
        this.capacita = capacita;
        testa.succ = coda;
        coda.prec = testa;
    }

private void stacca(Nodo nodo) {
    nodo.prec.succ = nodo.succ;
    nodo.succ.prec = nodo.prec;
}
private void inTesta(Nodo nodo) {
    nodo.succ = testa.succ;
    nodo.prec = testa;
    testa.succ.prec = nodo;
    testa.succ = nodo;
}

int prendi(int chiave) {
    Nodo nodo = mappa.get(chiave);
    if (nodo == null) {
        return -1;
    }
    stacca(nodo);
    inTesta(nodo);
    return nodo.valore;
}

    void metti(int chiave, int valore) {
        if (mappa.containsKey(chiave)) {
            stacca(mappa.get(chiave));
        } else if (mappa.size() == capacita) {
            Nodo vecchio = coda.prec;
            stacca(vecchio);
            mappa.remove(vecchio.chiave);
        }
        Nodo nodo = new Nodo(chiave, valore);
        mappa.put(chiave, nodo);
        inTesta(nodo);
    }
}

    public static void main(String[] args) {
        CacheLRU cache = new CacheLRU(2);
        cache.metti(1, 10);
        cache.metti(2, 20);
        System.out.println(cache.prendi(1));
        cache.metti(3, 30);
        System.out.println(cache.prendi(2) + " " + cache.prendi(3));
        cache.metti(4, 40);
        System.out.println(cache.prendi(1) + " " + cache.prendi(3) + " " + cache.prendi(4));
    }
